import { NgTemplateOutlet } from '@angular/common';
import { booleanAttribute, ChangeDetectionStrategy, Component, computed, contentChild, forwardRef, inject, InjectionToken, input, NgModule, numberAttribute, output, signal, TemplateRef, viewChild, ViewEncapsulation } from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import { MotionOptions } from '@primeuix/motion';
import { TimesCircle as TimesCircleIcon } from '@primeicons/angular/times-circle';
import { cn, focus, resolveFieldData, uuid } from '@primeuix/utils';
import { OverlayOptions, SharedModule } from 'primeng/api';
import { AutoComplete } from 'primeng/autocomplete';
import { PARENT_INSTANCE } from 'primeng/basecomponent';
import { BaseInput } from 'primeng/baseinput';
import { Bind } from 'primeng/bind';
import { Chip } from 'primeng/chip';
import type { AppendTo } from 'primeng/types/shared';
import type { InputTagsAddEvent, InputTagsCompleteEvent, InputTagsGroupTemplateContext, InputTagsItemTemplateContext, InputTagsOptionTemplateContext, InputTagsPassThrough, InputTagsRemoveEvent, InputTagsSelectEvent } from 'primeng/types/inputtags';
import { InputTagsStyle } from './style/inputtagsstyle';

const INPUTTAGS_INSTANCE = new InjectionToken<InputTags>('INPUTTAGS_INSTANCE');

export const INPUTTAGS_VALUE_ACCESSOR = {
    provide: NG_VALUE_ACCESSOR,
    useExisting: forwardRef(() => InputTags),
    multi: true
};

/**
 * InputTags is used to enter multiple tags with optional typeahead suggestions.
 * @group Components
 */
@Component({
    selector: 'p-inputtags, p-input-tags',
    standalone: true,
    imports: [NgTemplateOutlet, SharedModule, Bind, Chip, TimesCircleIcon, AutoComplete],
    template: `
        @for (item of modelValue(); track i + '_' + item; let i = $index) {
            @if (!itemTemplate()) {
                <p-chip [class]="cx('item', { i })" [pt]="ptm('pcChip')" [label]="getItemLabel(item)" [removable]="true" (onRemove)="removeItem($event, i)" [unstyled]="unstyled()">
                    <ng-template #removeicon>
                        @if (!removeIconTemplate()) {
                            <span [pBind]="ptm('chipIcon')" [class]="cx('chipIcon')">
                                <svg data-p-icon="times-circle" [class]="cx('chipIcon')" [attr.aria-hidden]="true" />
                            </span>
                        } @else {
                            <span [pBind]="ptm('chipIcon')" [attr.aria-hidden]="true">
                                <ng-container [ngTemplateOutlet]="removeIconTemplate()!" [ngTemplateOutletContext]="{ $implicit: item, index: i }"></ng-container>
                            </span>
                        }
                    </ng-template>
                </p-chip>
            } @else {
                <ng-container [ngTemplateOutlet]="itemTemplate()!" [ngTemplateOutletContext]="{ $implicit: item, index: i, onRemove: _removeItemBound }"></ng-container>
            }
        }
        <p-autocomplete
            #ac
            [typeahead]="typeahead()"
            [suggestions]="suggestions()"
            [optionLabel]="optionLabel()"
            [optionValue]="optionValue()"
            [optionDisabled]="optionDisabled()"
            [optionGroupLabel]="optionGroupLabel()"
            [optionGroupChildren]="optionGroupChildren()"
            [group]="group()"
            [delay]="delay()"
            [minQueryLength]="minQueryLength()"
            [completeOnFocus]="completeOnFocus()"
            [scrollHeight]="scrollHeight()"
            [appendTo]="$appendTo()"
            [overlayOptions]="overlayOptions()"
            [motionOptions]="motionOptions()"
            [panelStyle]="panelStyle()"
            [panelStyleClass]="panelStyleClass()"
            [autoOptionFocus]="autoOptionFocus()"
            [focusOnHover]="focusOnHover()"
            [placeholder]="_placeholder()"
            [tabindex]="tabindex()"
            [disabled]="$disabled()"
            [name]="name()"
            [inputStyle]="inputStyle()"
            [inputStyleClass]="$inputStyleClass()"
            [pt]="ptm('pcAutoComplete')"
            (completeMethod)="onAcSearch($event)"
            (onSelect)="onAcSelect($event)"
            (onFocus)="onInputFocus($event)"
            (onBlur)="onInputBlur($event)"
            (onShow)="onShow.emit()"
            (onHide)="onHide.emit()"
            (onInputKeydown)="onAcKeyDown($event)"
        >
            @if (optionTemplate()) {
                <ng-template #item let-item let-index="index">
                    <ng-container [ngTemplateOutlet]="optionTemplate()!" [ngTemplateOutletContext]="{ $implicit: item, index: index }"></ng-container>
                </ng-template>
            }
            @if (groupTemplate()) {
                <ng-template #group let-group>
                    <ng-container [ngTemplateOutlet]="groupTemplate()!" [ngTemplateOutletContext]="{ $implicit: group }"></ng-container>
                </ng-template>
            }
            @if (headerTemplate()) {
                <ng-template #header>
                    <ng-container [ngTemplateOutlet]="headerTemplate()!"></ng-container>
                </ng-template>
            }
            @if (footerTemplate()) {
                <ng-template #footer>
                    <ng-container [ngTemplateOutlet]="footerTemplate()!"></ng-container>
                </ng-template>
            }
        </p-autocomplete>
    `,
    providers: [INPUTTAGS_VALUE_ACCESSOR, InputTagsStyle, { provide: INPUTTAGS_INSTANCE, useExisting: InputTags }, { provide: PARENT_INSTANCE, useExisting: InputTags }],
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    host: {
        '[class]': "cx('root')",
        '[style]': "sx('root')",
        '[attr.role]': "'listbox'",
        '[attr.aria-orientation]': "'horizontal'",
        '[attr.aria-activedescendant]': 'focusedItemId()',
        '(click)': 'onContainerClick($event)',
        '(keydown)': 'onContainerKeyDown($event)'
    },
    hostDirectives: [Bind]
})
export class InputTags extends BaseInput<InputTagsPassThrough, any> {
    componentName = 'InputTags';

    $pcInputTags: InputTags | undefined = inject(INPUTTAGS_INSTANCE, { optional: true, skipSelf: true }) ?? undefined;

    bindDirectiveInstance = inject(Bind, { self: true });

    /**
     * Advisory information to display on input.
     * @group Props
     */
    placeholder = input<string>();

    /**
     * Maximum number of tags allowed.
     * @group Props
     */
    override max = input<any>();

    /**
     * Delimiter character or regex to split input into tags.
     * @group Props
     */
    delimiter = input<string | RegExp>();

    /**
     * Whether to allow duplicate tags.
     * @defaultValue false
     * @group Props
     */
    allowDuplicate = input(false, { transform: booleanAttribute });

    /**
     * Whether to add a tag when the input loses focus.
     * @defaultValue false
     * @group Props
     */
    addOnBlur = input(false, { transform: booleanAttribute });

    /**
     * Whether to add a tag on tab key press.
     * @defaultValue false
     * @group Props
     */
    addOnTab = input(false, { transform: booleanAttribute });

    /**
     * Whether to add tags on paste event.
     * @defaultValue false
     * @group Props
     */
    addOnPaste = input(false, { transform: booleanAttribute });

    /**
     * Index of the element in tabbing order.
     * @group Props
     */
    tabindex = input<number>();

    /**
     * Whether typeahead mode is active.
     * @defaultValue false
     * @group Props
     */
    typeahead = input(false, { transform: booleanAttribute });

    /**
     * An array of suggestions to display in the dropdown.
     * @group Props
     */
    suggestions = input<any[]>([]);

    /**
     * Property name or getter function for option label.
     * @group Props
     */
    optionLabel = input<string | ((item: any) => string)>();

    /**
     * Property name or getter function for option value.
     * @group Props
     */
    optionValue = input<string | ((item: any) => any)>();

    /**
     * Property name or getter function for disabled state.
     * @group Props
     */
    optionDisabled = input<string | ((item: any) => boolean)>();

    /**
     * Field name for option group label.
     * @defaultValue 'label'
     * @group Props
     */
    optionGroupLabel = input<string>('label');

    /**
     * Field name for option group children.
     * @defaultValue 'items'
     * @group Props
     */
    optionGroupChildren = input<string>('items');

    /**
     * Whether to display options as grouped.
     * @defaultValue false
     * @group Props
     */
    group = input(false, { transform: booleanAttribute });

    /**
     * Delay in ms between keystrokes before triggering search.
     * @defaultValue 300
     * @group Props
     */
    delay = input(300, { transform: numberAttribute });

    /**
     * Minimum number of characters to initiate a search.
     * @defaultValue 1
     * @group Props
     */
    minQueryLength = input(1, { transform: numberAttribute });

    /**
     * Whether to trigger search when input receives focus.
     * @defaultValue false
     * @group Props
     */
    completeOnFocus = input(false, { transform: booleanAttribute });

    /**
     * Maximum height of the suggestions panel.
     * @defaultValue '200px'
     * @group Props
     */
    scrollHeight = input('200px');

    /**
     * Target element to attach the overlay.
     * @defaultValue 'body'
     * @group Props
     */
    appendTo = input<AppendTo>('body');

    /**
     * Configuration for the overlay element.
     * @group Props
     */
    overlayOptions = input<OverlayOptions>();

    /**
     * Animation options for the overlay.
     * @group Props
     */
    motionOptions = input<MotionOptions | undefined>();

    /**
     * Inline style of the overlay panel.
     * @group Props
     */
    panelStyle = input<{ [klass: string]: any }>();

    /**
     * CSS class of the overlay panel.
     * @group Props
     */
    panelStyleClass = input<string>();

    /**
     * Inline style of the input field.
     * @group Props
     */
    inputStyle = input<{ [klass: string]: any }>();

    /**
     * CSS class of the input field.
     * @group Props
     */
    inputStyleClass = input<string>();

    /**
     * Whether to auto-focus first option when overlay shows.
     * @defaultValue false
     * @group Props
     */
    autoOptionFocus = input(false, { transform: booleanAttribute });

    /**
     * Whether hover focuses an option.
     * @defaultValue true
     * @group Props
     */
    focusOnHover = input(true, { transform: booleanAttribute });

    onAdd = output<InputTagsAddEvent>();

    onRemove = output<InputTagsRemoveEvent>();

    onFocus = output<FocusEvent>();

    onBlur = output<FocusEvent>();

    /**
     * Callback to invoke to search for suggestions.
     * @param {InputTagsCompleteEvent} event - Custom complete event.
     * @group Emits
     */
    completeMethod = output<InputTagsCompleteEvent>();

    /**
     * Callback to invoke when a suggestion is selected.
     * @param {InputTagsSelectEvent} event - Custom select event.
     * @group Emits
     */
    onSelect = output<InputTagsSelectEvent>();

    /**
     * Callback to invoke when the overlay is shown.
     * @group Emits
     */
    onShow = output<void>();

    /**
     * Callback to invoke when the overlay is hidden.
     * @group Emits
     */
    onHide = output<void>();

    itemTemplate = contentChild<TemplateRef<InputTagsItemTemplateContext>>('item', { descendants: false });

    removeIconTemplate = contentChild<TemplateRef<{ $implicit: any; index: number }>>('removeicon', { descendants: false });

    optionTemplate = contentChild<TemplateRef<InputTagsOptionTemplateContext>>('option', { descendants: false });

    groupTemplate = contentChild<TemplateRef<InputTagsGroupTemplateContext>>('group', { descendants: false });

    headerTemplate = contentChild<TemplateRef<void>>('header', { descendants: false });

    footerTemplate = contentChild<TemplateRef<void>>('footer', { descendants: false });

    autoCompleteRef = viewChild<AutoComplete>('ac');

    focused = signal(false);

    focusedItemIndex = signal(-1);

    _componentStyle = inject(InputTagsStyle);

    private _internalId = uuid('pn_id_');

    $id = computed(() => this._internalId);

    _placeholder = computed(() => this.placeholder());

    focusedItemId = computed(() => (this.focusedItemIndex() !== -1 ? `${this.$id()}_item_${this.focusedItemIndex()}` : null));

    $appendTo = computed(() => this.appendTo() ?? this.config?.overlayAppendTo());

    $inputStyleClass = computed(() => cn(this.cx('pcInputText'), this.inputStyleClass()) as string);

    _removeItemBound = this.removeItem.bind(this);

    private _pasteListener: ((e: ClipboardEvent) => void) | null = null;

    onAfterViewInit() {
        this.bindPasteListener();
    }

    onAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }

    onDestroy() {
        this.unbindPasteListener();
    }

    writeControlValue(value: any, setModelValue?: (value: any) => void) {
        setModelValue?.(value || []);
    }

    getItemLabel(item: any): string {
        const optLabel = this.optionLabel();

        if (optLabel && typeof item === 'object') {
            return typeof optLabel === 'function' ? optLabel(item) : resolveFieldData(item, optLabel);
        }

        return typeof item === 'object' ? JSON.stringify(item) : String(item);
    }

    addItem(event: Event, value: string) {
        const trimmed = value.trim();

        if (!trimmed) return;

        if (this.max() != null && (this.modelValue()?.length ?? 0) >= this.max()!) return;

        if (!this.allowDuplicate() && this.modelValue()?.includes(trimmed)) return;

        const newValue = [...(this.modelValue() || []), trimmed];

        this._updateModel(newValue);
        this.onAdd.emit({ originalEvent: event, value: trimmed });
        this.clearAcInput();
    }

    removeItem(event: Event, index: number) {
        if (this.$disabled()) return;

        const current = this.modelValue() || [];
        const removed = current[index];
        const newValue = current.filter((_: any, i: number) => i !== index);

        this._updateModel(newValue);
        this.onRemove.emit({ originalEvent: event, value: removed, index });
        setTimeout(() => this.autoCompleteRef()?.overlayViewChild()?.alignOverlay());
    }

    onContainerClick(event: MouseEvent) {
        if (this.$disabled()) return;

        const target = event.target as HTMLElement;

        if (target.closest?.('[data-p-focused]')) return;

        this.focusAcInput();
    }

    onContainerKeyDown(event: KeyboardEvent) {
        if (this.$disabled()) return;

        switch (event.code) {
            case 'ArrowLeft':
                this.onArrowLeftInContainer(event);
                break;
            case 'ArrowRight':
                this.onArrowRightInContainer(event);
                break;
            case 'Backspace':
                this.onBackspaceInContainer(event);
                break;
        }
    }

    onAcSearch(event: any) {
        this.completeMethod.emit({ originalEvent: event.originalEvent, query: event.query });
    }

    onAcSelect(event: any) {
        const option = event.value;
        const optValue = this.optionValue();
        const value = optValue ? (typeof optValue === 'function' ? optValue(option) : resolveFieldData(option, optValue)) : option;

        if (this.max() != null && (this.modelValue()?.length ?? 0) >= this.max()!) {
            this.clearAcInput();

            return;
        }

        const newModelValue = [...(this.modelValue() || []), value];

        this._updateModel(newModelValue);
        this.onAdd.emit({ originalEvent: event.originalEvent, value });
        this.onSelect.emit({ originalEvent: event.originalEvent, value: option });

        // Clear the AC's internal value and input after selection
        setTimeout(() => {
            const ac = this.autoCompleteRef();

            if (ac) {
                ac.writeValue(null);

                if (ac.inputEL()?.nativeElement) {
                    ac.inputEL()!.nativeElement.value = '';
                }
            }
        });
    }

    onAcKeyDown(event: KeyboardEvent) {
        const ac = this.autoCompleteRef();
        const inputValue = ac?.inputEL()?.nativeElement?.value || '';

        switch (event.code) {
            case 'Enter':
            case 'NumpadEnter':
                if (ac?.overlayVisible() && ac?.focusedOptionIndex() !== -1) {
                    return;
                }

                // Otherwise add free text tag
                if (inputValue) {
                    this.addItem(event, inputValue);
                    event.preventDefault();
                    event.stopPropagation();
                }

                break;
            case 'Backspace':
                if (!inputValue && this.modelValue()?.length > 0) {
                    this.removeItem(event, this.modelValue().length - 1);
                    event.stopPropagation();
                }

                break;
            case 'Tab':
                if (this.addOnTab() && inputValue) {
                    this.addItem(event, inputValue);
                }

                break;
            default:
                this.handleDelimiter(event);
                break;
        }
    }

    onInputFocus(event: any) {
        if (this.$disabled()) return;

        this.focused.set(true);
        this.focusedItemIndex.set(-1);
        this.onFocus.emit(event);
    }

    onInputBlur(event: any) {
        if (this.addOnBlur()) {
            const inputValue = this.autoCompleteRef()?.inputEL()?.nativeElement?.value || '';

            if (inputValue) {
                this.addItem(event, inputValue);
            }
        }

        this.focused.set(false);
        this.onModelTouched();
        this.onBlur.emit(event);
    }

    private handleDelimiter(event: KeyboardEvent) {
        const delimiter = this.delimiter();

        if (!delimiter) return;

        const isMatch = typeof delimiter === 'string' ? event.key === delimiter : event.key.match(delimiter);

        if (!isMatch) return;

        event.preventDefault();
        const inputValue = this.autoCompleteRef()?.inputEL()?.nativeElement?.value || '';

        if (inputValue) {
            this.addItem(event, inputValue);
        }
    }

    private onArrowLeftInContainer(_event: KeyboardEvent) {
        const current = this.focusedItemIndex();
        const length = this.modelValue()?.length ?? 0;

        if (length === 0) return;

        if (current <= 0) {
            this.focusedItemIndex.set(length - 1);
        } else {
            this.focusedItemIndex.set(current - 1);
        }
    }

    private onArrowRightInContainer(_event: KeyboardEvent) {
        const current = this.focusedItemIndex();
        const length = this.modelValue()?.length ?? 0;

        if (length === 0) return;

        if (current >= length - 1) {
            this.focusedItemIndex.set(-1);
            this.focusAcInput();
        } else {
            this.focusedItemIndex.set(current + 1);
        }
    }

    private onBackspaceInContainer(event: KeyboardEvent) {
        const current = this.focusedItemIndex();

        if (current !== -1) {
            this.removeItem(event, current);
            const length = this.modelValue()?.length ?? 0;

            if (length === 0) {
                this.focusedItemIndex.set(-1);
                this.focusAcInput();
            } else if (current >= length) {
                this.focusedItemIndex.set(length - 1);
            }
        }
    }

    private clearAcInput() {
        const ac = this.autoCompleteRef();

        if (ac?.inputEL()?.nativeElement) {
            ac.inputEL()!.nativeElement.value = '';
        }
    }

    private focusAcInput() {
        focus(this.autoCompleteRef()?.inputEL()?.nativeElement);
    }

    private bindPasteListener() {
        const inputEl = this.autoCompleteRef()?.inputEL()?.nativeElement;

        if (inputEl) {
            this._pasteListener = (event: ClipboardEvent) => this.onInputPaste(event);
            inputEl.addEventListener('paste', this._pasteListener);
        }
    }

    private unbindPasteListener() {
        const inputEl = this.autoCompleteRef()?.inputEL()?.nativeElement;

        if (inputEl && this._pasteListener) {
            inputEl.removeEventListener('paste', this._pasteListener);
            this._pasteListener = null;
        }
    }

    private onInputPaste(event: ClipboardEvent) {
        if (!this.addOnPaste()) return;

        const pastedData = event.clipboardData?.getData('Text');

        if (!pastedData) return;

        const delimiter = this.delimiter();

        if (delimiter) {
            pastedData.split(delimiter).forEach((v: string) => this.addItem(event, v));
        } else {
            this.addItem(event, pastedData);
        }

        this.clearAcInput();
        event.preventDefault();
    }

    private _updateModel(value: any[]) {
        this.writeModelValue(value);
        this.onModelChange(value);
    }
}

@NgModule({
    imports: [InputTags, SharedModule],
    exports: [InputTags, SharedModule]
})
export class InputTagsModule {}
